const r2 = v => Math.round(v * 100) / 100;
const tr = (d, c, extra = '') => `<path d="${d}" fill="${c}" fill-rule="evenodd"${extra}/>`;
// Smooth curve through points (Catmull-Rom as cubic Beziers), without the initial M.
function seg(P) {
  let d = '';
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(i - 1, 0)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(i + 2, P.length - 1)];
    d += `C${r2(p1[0] + (p2[0] - p0[0]) / 6)} ${r2(p1[1] + (p2[1] - p0[1]) / 6)} ${r2(p2[0] - (p3[0] - p1[0]) / 6)} ${r2(p2[1] - (p3[1] - p1[1]) / 6)} ${r2(p2[0])} ${r2(p2[1])}`;
  }
  return d;
}
// Closed outline from a half-width profile [[y, halfWidth], ...] (top to bottom), mirrored about x=100.
function outline(pts) {
  const R = pts.map(([y, h]) => [100 + h, y]);
  const L = R.map(([x, y]) => [200 - x, y]).reverse();
  return `M${r2(L[L.length - 1][0])} ${r2(R[0][1])}H${r2(R[0][0])}${seg(R)}H${r2(L[0][0])}${seg(L)}Z`;
}
// A highlight line following the profile at k times the half width, between y0 and y1.
function spec(pts, k, y0, y1) {
  const P = pts.filter(([y]) => y >= y0 && y <= y1).map(([y, h]) => [r2(100 + h * k), y]);
  return `M${P[0][0]} ${P[0][1]}${seg(P)}`;
}
// Crown cap: hw half width, from y0 (top) to y1 (skirt edge).
function crown(hw, y0, y1, ink) {
  let flutes = '';
  for (let x = 100 - hw + 1.6; x < 100 + hw - 1; x += 2.4) flutes += `M${r2(x)} ${r2(y0 + 3)}V${r2(y1 - .3)}`;
  return `<path d="M${r2(100 - hw)} ${y1}L${r2(100 - hw + .4)} ${r2(y0 + 2.2)}Q100 ${r2(y0 - 1)} ${r2(100 + hw - .4)} ${r2(y0 + 2.2)}L${r2(100 + hw)} ${y1}Z" fill="${ref('crown')}" stroke="${ink}" stroke-width=".6"/>`
    + `<path d="${flutes}" stroke="${ink}" stroke-width=".55" opacity=".35"/>`
    + `<path d="M${r2(100 - hw + 1.5)} ${r2(y0 + 1.9)}Q100 ${r2(y0 - .2)} ${r2(100 + hw - 1.5)} ${r2(y0 + 1.9)}" fill="none" stroke="#fff8dc" stroke-width=".8" opacity=".6"/>`;
}
const crownDef = (hi, mid, lo) => `<linearGradient id="__ID__crown"><stop stop-color="${lo}"/><stop offset=".28" stop-color="${hi}"/><stop offset=".6" stop-color="${mid}"/><stop offset="1" stop-color="${lo}"/></linearGradient>`;

// House glass bottle (after the Good pacifico-clara helper): liquid (optionally below liqY, empty glass above),
// label inside the clip, glass and shade overlays, two highlight lines, closure on top.
function bottle(slug, title, {pts, liq, emptyGlass, liqY = 0, inside = '', label, closure, defs = '', specs}) {
  const shape = outline(pts), W = Math.max(...pts.map(p => p[1]));
  const fill = emptyGlass ? ref('empty') : ref('liquid');
  const liquid = emptyGlass ? `<path d="M60 ${liqY}H140V240H60Z" fill="${ref('liquid')}"/><path d="M60 ${liqY + .3}H140" stroke="${liq.dark}" stroke-width="1" opacity=".45"/>` : '';
  const body = `${shadow(42)}<path d="${shape}" fill="${fill}"/>
<g clip-path="${ref('bottleclip')}">${liquid}${inside}${label}<path d="${shape}" fill="${ref('glass')}" opacity=".4"/><path d="${shape}" fill="${ref('shade')}" opacity=".6"/>
<path d="${specs[0]}" fill="none" stroke="#fffbe8" stroke-opacity=".3" stroke-width="2.6" stroke-linecap="round"/><path d="${specs[1]}" fill="none" stroke="#fffbe8" stroke-opacity=".2" stroke-width="1.1" stroke-linecap="round"/></g>
<path d="${shape}" fill="none" stroke="${liq.dark}" stroke-width=".7"/>${closure}<path d="M${r2(100 - W + 6)} 231q${r2(W - 6)} 5 ${r2(2 * (W - 6))} 0" fill="none" stroke="#fff7d5" stroke-opacity=".3" stroke-width="1.1"/>`;
  const g = `gradientUnits="userSpaceOnUse" x1="${r2(100 - W)}" x2="${r2(100 + W)}" y1="0" y2="0"`;
  const d = `<clipPath id="__ID__bottleclip"><path d="${shape}"/></clipPath><linearGradient id="__ID__liquid" ${g}><stop stop-color="${liq.dark}"/><stop offset=".25" stop-color="${liq.light}"/><stop offset=".58" stop-color="${liq.glass}"/><stop offset="1" stop-color="${liq.dark}"/></linearGradient>`
    + (emptyGlass ? `<linearGradient id="__ID__empty" ${g}><stop stop-color="${emptyGlass[1]}"/><stop offset=".3" stop-color="${emptyGlass[0]}"/><stop offset=".7" stop-color="${emptyGlass[0]}" stop-opacity=".85"/><stop offset="1" stop-color="${emptyGlass[1]}"/></linearGradient>` : '');
  return wrap(slug, title, body, d + defs);
}

